    rs = sorted(r for r, c in points)
    cs = sorted(c for r, c in points)
    def median_choices(vals):
        n = len(vals)
        if n % 2:
            return [vals[n // 2]]
        return sorted(set((vals[n // 2 - 1], vals[n // 2])))
    out = [row[:] for row in grid]
    def paint(r, c):
        if out[r][c] == 0:
            out[r][c] = 3
    # Choose the cheaper rectilinear backbone; in a tie, use a vertical backbone.
    hr = min(median_choices(rs), key=lambda r: sum(abs(r-pr) for pr, pc in points))
    hc = min(median_choices(cs), key=lambda c: sum(abs(c-pc) for pr, pc in points))
    hcost = max(cs) - min(cs) + sum(abs(pr-hr) for pr, pc in points)
    vcost = max(rs) - min(rs) + sum(abs(pc-hc) for pr, pc in points)
    if hcost < vcost:
        for c in range(min(cs), max(cs)+1):
            paint(hr, c)
        for r, c in points:
            for rr in range(min(r, hr), max(r, hr)+1):
                paint(rr, c)
    else:
        for r in range(min(rs), max(rs)+1):
            paint(r, hc)
        for r, c in points:
